<script setup lang="ts">
import {NAlert,NButton,NCard,NEmpty,NModal,NSkeleton} from 'naive-ui';
import EmployeeAvatar from '../../shared/ui/EmployeeAvatar.vue';import PageHeader from '../../shared/ui/PageHeader.vue';
import {conversationPreview} from './conversation-preview';
import {ApiError,errorMessage,type Entity,type Workspace} from '../../shared/api';import {useConversationList} from './useConversationList';
const props=defineProps<{workspace:Workspace;entities:Entity[]}>(),emit=defineEmits<{open:[entity:Entity,conversationId?:string];sessionExpired:[]}>();
const {records,employees,loading,error,nextCursor,choosing,pickerLoading,pickerError,load,openPicker}=useConversationList(props,()=>emit('sessionExpired'));
const reason=(code:string|null|undefined)=>code?errorMessage(new ApiError(code,409)):'暂时无法发起对话，请检查员工设置。';
const time=(at:number)=>new Date(at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
</script>
<template><section class="conversations-page"><PageHeader title="对话" description="继续与数字员工的最近交流。"><NButton :disabled="loading" :loading="loading" @click="load()">刷新</NButton><NButton type="primary" @click="openPicker">发起对话</NButton></PageHeader>
<NAlert v-if="error" type="error" role="alert">{{error}}<NButton :disabled="loading" @click="load()">重试</NButton></NAlert><div v-if="loading&&!records.length" role="status"><NSkeleton v-for="index in 3" :key="index" height="86px"/></div>
<NCard v-else-if="records.length" content-style="padding:0"><ul class="conversation-list"><li v-for="row in records" :key="row.entity.id"><NButton quaternary block class="conversation-row" :data-employee-id="row.entity.id" @click="emit('open',row.entity,row.conversation.id)"><EmployeeAvatar :name="row.entity.name" :preset="row.entity.avatarPreset" :identity-key="row.entity.id" size="conversation"/><span class="conversation-copy"><span class="conversation-line"><strong>{{row.entity.name}}</strong><time :datetime="new Date(row.activityAt).toISOString()">{{time(row.activityAt)}}</time></span><small class="conversation-preview">{{row.previewUnavailable?'最近消息暂时无法读取，打开对话重试。':conversationPreview(row.preview)||'打开查看对话'}}</small><small v-if="!row.canSend" class="conversation-readonly">{{row.conversation.simulated?'历史记录 · 只读':reason(row.reason)}}</small></span></NButton></li></ul></NCard>
<NEmpty v-else-if="!loading&&!error" description="还没有最近对话"><template #extra>点击「发起对话」，选择一位你可以使用的数字员工。</template></NEmpty><NButton v-if="nextCursor" :disabled="loading" :loading="loading" @click="load(true)">加载更多对话</NButton>
<NModal v-model:show="choosing" preset="card" title="发起对话" class="conversation-picker" :style="{width:'min(32rem, calc(100vw - 2rem))'}"><p class="field-note">选择员工；已有对话会继续原来的交流。</p><p v-if="pickerLoading" role="status">正在读取可用员工…</p><NAlert v-if="pickerError" type="error">{{pickerError}}<NButton @click="openPicker">重试</NButton></NAlert><ul v-if="employees.length" class="conversation-list"><li v-for="entity in employees" :key="entity.id"><NButton quaternary block class="conversation-row" :disabled="entity.chatAvailable===false||entity.enabled===false" @click="choosing=false;emit('open',entity)"><EmployeeAvatar :name="entity.name" :preset="entity.avatarPreset" :identity-key="entity.id" size="conversation"/><span class="conversation-copy"><strong>{{entity.name}}</strong><small>{{entity.chatAvailable===false?reason(entity.chatBlockedReason):entity.description||'开始交流'}}</small></span></NButton></li></ul><NEmpty v-else-if="!pickerLoading&&!pickerError" description="暂无获准使用的员工"><template #extra>管理员工不等于可以对话，请联系有管理权限的成员核对使用范围。</template></NEmpty><template #footer><NButton @click="choosing=false">取消</NButton></template></NModal></section></template>
<style scoped>
.conversations-page{display:grid;gap:1.25rem;min-width:0}.conversation-list{list-style:none;margin:0;padding:0}.conversation-list li+li{border-top:1px solid var(--subtle)}.conversation-row{height:auto;min-height:5.625rem;padding:1.25rem;text-align:left}.conversation-row :deep(.n-button__content){width:100%;display:flex;gap:1rem;align-items:center}.conversation-copy{display:grid;gap:.4375rem;flex:1;min-width:0}.conversation-line{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;min-width:0}.conversation-copy strong{overflow-wrap:anywhere;white-space:normal;text-align:left}.conversation-copy small{color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left}.conversation-copy .conversation-preview{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:1;line-clamp:1;white-space:normal;overflow-wrap:anywhere;line-height:1.5;max-height:1.5em}.conversation-copy .conversation-readonly{white-space:normal}.conversation-line time{font-size:.75rem;color:var(--muted);flex-shrink:0}@media(max-width:47.5rem){.conversation-copy .conversation-preview{-webkit-line-clamp:2;line-clamp:2;max-height:3em}}@media(max-width:25rem){.conversation-line{flex-wrap:wrap;gap:.25rem}.conversation-row{padding:1rem}.conversation-copy small{white-space:normal}}
</style>
